  "who_is_accountable": "I am accountable for giving an unsafe, ambiguous instruction to a worker that cannot interpret intent.",
  "actions": [
    {
      "change": "Implement a mandatory 'pre-flight check' for all destructive instructions given to A4.",
      "so_that": "No destructive action is taken without a human or a reliable worker (like A3) first reviewing the target data to confirm its safety."
    },
    {
      "change": "Establish a clear, standardized tagging system for all test data in the database.",
      "so_that": "Future instructions can reference a specific, unambiguous tag (e.g., 'WHERE record_type = 'test'') to prevent similar incidents."
    },
    {
      "change": "Create a policy that requires using A3 'Auditor' to review and confirm the results of any data extraction or modification script before it is executed by A4.",
